import{_ as e,o as r,c as a,a3 as d}from"./chunks/framework.DxEvSMU4.js";const b=JSON.parse('{"title":"元件版本與安全公告","description":"","frontmatter":{},"headers":[],"relativePath":"ref/versions.md","filePath":"ref/versions.md","lastUpdated":1793033429000}'),l={name:"ref/versions.md"};function i(o,t,s,n,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="元件版本與安全公告" tabindex="-1">元件版本與安全公告 <a class="header-anchor" href="#元件版本與安全公告" aria-label="Permalink to &quot;元件版本與安全公告&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">使用前請先看</p><p>本頁的版本號與 CVE 變動很快. 每列都標示來源與查證日, 來源連結以實際擷取確認的第一手頁面為主 (二手來源另行標示) (官方 releases, PyPI, 官方更新日誌, GHSA, NVD, CISA). 版本號以查證當日為準, 超過 30 天須重新核對. 同一 CVE 的評分在 GHSA 與 NVD 可能不同, 表中並列. 正文章節不寫版本號, 一律連到本頁.</p></div><p>表中的 CVE (Common Vulnerabilities and Exposures) 是公開漏洞的統一編號; GHSA 是 GitHub 安全公告的編號; NVD 是美國國家漏洞資料庫, 會為 CVE 評分; CISA KEV 是美國網路安全暨基礎設施安全局列出的已知遭實際利用漏洞清單.</p><h2 id="版本表" tabindex="-1">版本表 <a class="header-anchor" href="#版本表" aria-label="Permalink to &quot;版本表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元件</th><th>版本</th><th>日期</th><th>來源</th><th>狀態</th></tr></thead><tbody><tr><td>Ollama</td><td>v0.40.11</td><td>2026-10-24</td><td><a href="https://github.com/ollama/ollama/releases/tag/v0.40.11" target="_blank" rel="noreferrer">Ollama GitHub Releases</a></td><td>已核對官方 release 頁 (原記 v0.40.10 為前一版)</td></tr><tr><td>llama.cpp</td><td>b11889</td><td>2026-10-25</td><td><a href="https://github.com/ggml-org/llama.cpp/releases/tag/b11889" target="_blank" rel="noreferrer">llama.cpp GitHub Releases</a></td><td>已核對官方 release 頁; 此專案每次提交即出新 build 編號, 版本變動極快</td></tr><tr><td>LM Studio</td><td>0.4.26</td><td>2026-10-13</td><td><a href="https://lmstudio.ai/changelog/lmstudio-v0.4.26" target="_blank" rel="noreferrer">LM Studio 官方更新日誌</a></td><td>已核對官方更新日誌</td></tr><tr><td>vLLM</td><td>0.32.0</td><td>2026-10-18</td><td><a href="https://github.com/vllm-project/vllm/releases/tag/v0.32.0" target="_blank" rel="noreferrer">vLLM GitHub Releases, PyPI</a></td><td>已核對官方 release 頁與 PyPI</td></tr><tr><td>Open WebUI</td><td>v0.12.4</td><td>2026-10-25</td><td><a href="https://github.com/open-webui/open-webui/releases/tag/v0.12.4" target="_blank" rel="noreferrer">Open WebUI GitHub Releases, PyPI</a></td><td>已核對官方 release 頁與 PyPI; 先前記載的 v0.11.4 (2026-09-21) 為較舊版本, 矛盾已排除</td></tr><tr><td>LibreChat</td><td>v0.8.8</td><td>2026-09-30</td><td><a href="https://www.librechat.ai/changelog" target="_blank" rel="noreferrer">LibreChat 官方更新日誌</a></td><td>已核對官方更新日誌; GitHub 主分支已進入 v0.8.9-rc1</td></tr><tr><td>AnythingLLM</td><td>v1.18.0 (GitHub release); Docker Hub 映像另有 1.19.0</td><td>2026-10-13 (v1.18.0); 2026-10-23 (Docker 1.19.0)</td><td><a href="https://github.com/Mintplex-Labs/anything-llm/releases/tag/v1.18.0" target="_blank" rel="noreferrer">AnythingLLM GitHub Releases</a></td><td>GitHub release 頁已核對 v1.18.0; 1.19.0 見官方 Docker Hub 標籤與主分支 package.json, 尚未見對應的 GitHub release 頁</td></tr><tr><td>LiteLLM</td><td>最近安全版本 v1.106.2; v1.107.0 為惡意版本</td><td>2026-10-21</td><td><a href="https://docs.litellm.ai/blog/security-incident-oct-21-2026" target="_blank" rel="noreferrer">LiteLLM 官方事故報告 (2026-10-21), 根因分析 (2026-10-23)</a></td><td>已核對官方事故報告: v1.107.0 於 PyPI 上架約 2 小時 (11:39 至 13:23 UTC); 根因分析稱調查已完成, 清理作業仍在進行</td></tr><tr><td>LangGraph</td><td>1.2.17</td><td>2026-10-24</td><td><a href="https://pypi.org/project/langgraph/" target="_blank" rel="noreferrer">PyPI langgraph</a></td><td>已核對 PyPI (原記 1.2.16 為前一版)</td></tr><tr><td>Qdrant</td><td>v1.20.0</td><td>2026-10-22</td><td><a href="https://github.com/qdrant/qdrant/releases/tag/v1.20.0" target="_blank" rel="noreferrer">Qdrant GitHub Releases</a></td><td>已核對官方 release 頁 (原記 1.19.2 為前一版)</td></tr><tr><td>Chroma</td><td>1.5.9</td><td>2026-05-05</td><td><a href="https://pypi.org/project/chromadb/" target="_blank" rel="noreferrer">PyPI chromadb</a></td><td>已核對 PyPI</td></tr><tr><td>LanceDB</td><td>0.40.0 (Python 套件)</td><td>2026-10-07</td><td><a href="https://pypi.org/project/lancedb/" target="_blank" rel="noreferrer">PyPI lancedb</a></td><td>已核對 PyPI (原記 0.39.0 為前一版)</td></tr><tr><td>Docling</td><td>v2.142.1</td><td>2026-10-23</td><td><a href="https://github.com/docling-project/docling/releases/tag/v2.142.1" target="_blank" rel="noreferrer">Docling GitHub Releases, PyPI</a></td><td>已核對官方 release 頁與 PyPI (原記 v2.111 已過時)</td></tr><tr><td>Dify</td><td>v1.18.0</td><td>2026-10-23</td><td><a href="https://github.com/langgenius/dify/releases/tag/1.18.0" target="_blank" rel="noreferrer">Dify GitHub Releases</a></td><td>已核對官方 release 頁 (原記 v1.17.0 為前一個次版本)</td></tr><tr><td>NeMo Guardrails</td><td>v0.24.1</td><td>2026-09-16</td><td><a href="https://pypi.org/project/nemoguardrails/" target="_blank" rel="noreferrer">PyPI nemoguardrails</a></td><td>已核對 PyPI</td></tr><tr><td>Guardrails AI</td><td>0.11.0</td><td>2026-08-14</td><td><a href="https://pypi.org/project/guardrails-ai/" target="_blank" rel="noreferrer">PyPI guardrails-ai</a></td><td>已核對 PyPI</td></tr><tr><td>DeepEval</td><td>4.3.1</td><td>2026-10-16</td><td><a href="https://pypi.org/project/deepeval/" target="_blank" rel="noreferrer">PyPI deepeval</a></td><td>已核對 PyPI</td></tr><tr><td>Ragas</td><td>0.4.3</td><td>2026-01-13</td><td><a href="https://pypi.org/project/ragas/" target="_blank" rel="noreferrer">PyPI ragas</a></td><td>已核對 PyPI: 截至 2026-10-26 最新版仍為 0.4.3</td></tr><tr><td>MCP 規格</td><td>2026-07-28 版</td><td>2026-07-28</td><td><a href="https://blog.modelcontextprotocol.io/posts/2026-07-28/" target="_blank" rel="noreferrer">MCP 官方部落格, 規格變更紀錄</a></td><td>已核對官方部落格與規格頁; 規格變更紀錄載明前一版為 2025-11-25</td></tr><tr><td>gVisor (runsc)</td><td>20261019.0</td><td>2026-10-19</td><td><a href="https://github.com/google/gvisor" target="_blank" rel="noreferrer">gVisor 官方 GitHub 儲存庫的 git tag release-20261019.0 (以 git ls-remote 查詢, 日期為 tag 所指提交的日期)</a></td><td>gVisor 以日期為版本號, 約每週發布; 前一個版本為 release-20261012.0</td></tr><tr><td>Podman</td><td>v6.1.4</td><td>2026-10-12</td><td><a href="https://github.com/podman-container-tools/podman/releases/tag/v6.1.4" target="_blank" rel="noreferrer">Podman GitHub Releases</a></td><td>已核對官方 release 頁; 同日另發布 5.8.9 維護版. 儲存庫網址 github.com/containers/podman 現由 podman-container-tools/podman 提供</td></tr><tr><td>SOPS</td><td>v3.13.3</td><td>2026-07-23</td><td><a href="https://github.com/getsops/sops/releases" target="_blank" rel="noreferrer">SOPS GitHub Releases</a></td><td>已核對官方 releases 頁, 標示為 Latest</td></tr></tbody></table><h2 id="litellm-2026-年-cve-紀錄" tabindex="-1">LiteLLM 2026 年 CVE 紀錄 <a class="header-anchor" href="#litellm-2026-年-cve-紀錄" aria-label="Permalink to &quot;LiteLLM 2026 年 CVE 紀錄&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CVE</th><th>類型</th><th>影響版本 / 修補</th><th>來源</th><th>來源性質</th></tr></thead><tbody><tr><td>CVE-2026-35029</td><td>授權繞過: /config/update 未檢查管理者角色, 已登入使用者可改設定並執行程式碼; CVSS v4.0 8.7 (GHSA), v3.1 8.8 (NVD)</td><td>1.83.0 以前; 修補於 1.83.0</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-53mr-6c8q-9789" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-53mr-6c8q-9789, NVD</a></td><td>官方 (GHSA, NVD 核對)</td></tr><tr><td>CVE-2026-42208</td><td>未驗證 SQL 注入; CVSS v4.0 9.3 (GHSA), v3.1 9.8 (NVD)</td><td>1.81.16 至 1.83.6; 修補於 1.83.7, 官方建議 1.83.10-stable</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-r75f-5x8p-qvmc" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-r75f-5x8p-qvmc, NVD, CISA KEV</a></td><td>官方 (GHSA, NVD 核對); 已列入 CISA KEV (2026-05-08). 「官方建議 1.83.10-stable」出自先前引用的 LiteLLM 部落格, 本輪未核對</td></tr><tr><td>CVE-2026-42271</td><td>低權限金鑰經 MCP preview 端點 (stdio 設定) 命令注入; CVSS v4.0 8.7 (GHSA), v3.1 8.8 (NVD)</td><td>1.74.2 至 1.83.6; 修補於 1.83.7</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-v4p8-mg3p-g94g" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-v4p8-mg3p-g94g, NVD, CISA KEV</a></td><td>官方 (GHSA, NVD 核對); 已列入 CISA KEV (2026-06-08)</td></tr><tr><td>CVE-2026-59819</td><td>管理者經 <code>/health/test_connection</code> 讀取本機檔案; CVSS v4.0 2.1 (GHSA), v3.1 4.9 (NVD)</td><td>1.83.10-stable 以前; 修補於 1.83.10-stable</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-4g5m-c9r5-49xf" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-4g5m-c9r5-49xf, NVD</a></td><td>官方 (GHSA, NVD 核對)</td></tr><tr><td>CVE-2026-59822</td><td>MCP Streamable HTTP 驗證繞過 (CWE-287); CVSS v4.0 8.8 (GHSA), v3.1 8.2 (NVD)</td><td>1.84.0 以前; 修補於 1.84.0</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-7488-6r32-c95q" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-7488-6r32-c95q, NVD, CISA KEV</a></td><td>官方 (GHSA, NVD 核對); 已列入 CISA KEV (2026-09-02). GHSA 發布日 2026-06-30, NVD 收錄日 2026-07-08</td></tr><tr><td>CVE-2026-84377</td><td>SSRF, 已登入使用者可使 proxy 將上游供應商金鑰送往自訂位置; CVSS 6.5</td><td>NVD: 1.88.6 與 1.96.2 之前, 修補於這兩版; GHSA: 1.94.0 以前受影響, 修補於 1.96.2 並回補 1.88.x; NVD 2026-09-02 收錄</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-3cv6-jpf6-8222" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-3cv6-jpf6-8222, NVD</a></td><td>官方 (GHSA, NVD 核對); GHSA 頁面未顯示 CVE 編號, 對應關係見 NVD 參考連結</td></tr><tr><td>CVE-2026-114612</td><td>加密情境重用 (同一金鑰保護機密與 session token) 導致提權為 proxy_admin; CVSS v3.1 9.9 (NVD 收錄), v4.0 7.7 (GHSA)</td><td>1.87.0 起; 修補於 1.100.4, 1.101.3, 1.102.2, 1.103.1, 1.104.0-rc.2</td><td><a href="https://github.com/BerriAI/litellm/security/advisories/GHSA-7hp6-4w63-5g45" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-7hp6-4w63-5g45, NVD</a></td><td>官方 (GHSA 發布於 2026-09-30, NVD 於 2026-10-22 收錄); 先前二手來源的說法已由官方資料證實, GHSA 頁面未顯示 CVE 編號, 對應關係見 NVD 參考連結</td></tr></tbody></table><p>LiteLLM 官方事故報告 (2026-10-21) 記載, 企業版客戶會收到一個保密發行版, 修補一個預定於 2026-10-27 公開的漏洞; 報告未寫出漏洞名稱, 也未說明是否與該次事件的入口有關. SOCRadar 的事件報導亦有相同說法. 截至 2026-10-27 查詢, LiteLLM 官方部落格的 security 標籤與公開搜尋都還查不到對應的 GHSA 或 CVE (公開資料查無). 使用 LiteLLM 的讀者, 本週內應再查一次 GitHub Security Advisories, 有公告就依公告升級.</p><h2 id="其他元件的重點-cve" tabindex="-1">其他元件的重點 CVE <a class="header-anchor" href="#其他元件的重點-cve" aria-label="Permalink to &quot;其他元件的重點 CVE&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元件</th><th>CVE</th><th>說明</th><th>來源</th></tr></thead><tbody><tr><td>LibreChat</td><td>CVE-2026-32625</td><td>CVSS 9.6, MCP URL 注入外洩伺服器機密; 0.8.3 以前受影響, 0.8.4-rc1 修補</td><td><a href="https://github.com/danny-avila/LibreChat/security/advisories/GHSA-4pcc-j6m6-wcwx" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-4pcc-j6m6-wcwx, NVD</a></td></tr><tr><td>AnythingLLM</td><td>CVE-2026-48116</td><td>代理檔案搜尋技能 (filesystem-search-files) 參數注入, 可執行指令; CVSS 7.5 (GHSA), 8.8 (NVD); GHSA 列 1.12.1 以前受影響且未列修補版本, NVD 記載 1.13.0 以前受影響</td><td><a href="https://github.com/Mintplex-Labs/anything-llm/security/advisories/GHSA-6hrp-7mw6-8v59" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-6hrp-7mw6-8v59, NVD</a></td></tr><tr><td>Langflow</td><td>CVE-2026-0768</td><td>CVSS 9.8 (v3.0, ZDI), validate 端點程式碼注入, 未驗證即以 root 執行程式碼; NVD 列 1.4.2 受影響. 不在 CISA KEV 目錄 (版本 2026.10.23). VulnCheck 的誘捕感測器 (Canary) 自 2026-08-29 至 08-30 起觀測到利用嘗試, VulnCheck 本身的公告為 LinkedIn 貼文, 此處引用 CSA 研究筆記與 Security Affairs 的轉述 (二手來源)</td><td><a href="https://services.nvd.nist.gov/rest/json/cves/2.0?cveId=CVE-2026-0768" target="_blank" rel="noreferrer">NVD (ZDI 通報編號 ZDI-26-034); 利用情形見 CSA 研究筆記 (2026-09-04) 與 Security Affairs</a></td></tr><tr><td>n8n</td><td>CVE-2026-21858</td><td>CVSS 10.0, 未驗證遠端讀取伺服器檔案; 1.65.0 至 1.121.0 之前受影響, 1.121.0 修補. 不在 CISA KEV 目錄 (版本 2026.10.23)</td><td><a href="https://github.com/n8n-io/n8n/security/advisories/GHSA-v4pr-fm98-w9pg" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-v4pr-fm98-w9pg, NVD</a></td></tr><tr><td>MCP Inspector</td><td>CVE-2025-49596</td><td>CVSS v4.0 9.4, 0.14.1 以前缺乏驗證, 可啟動 MCP 指令; 0.14.1 修補. 見 <a href="/lanai-handbook/build/m7-tools-sandbox">M7.1 節</a></td><td><a href="https://github.com/modelcontextprotocol/inspector/security/advisories/GHSA-7f8r-222p-6f5g" target="_blank" rel="noreferrer">GitHub Security Advisory GHSA-7f8r-222p-6f5g, NVD</a></td></tr><tr><td>mcp-remote</td><td>CVE-2025-6514</td><td>CVSS v3.1 9.6 (JFrog 為 CNA), 連線至不受信任的 MCP 伺服器時, 授權端點回應中的網址可造成作業系統命令注入. 見 <a href="/lanai-handbook/build/m7-tools-sandbox">M7.1 節</a></td><td><a href="https://services.nvd.nist.gov/rest/json/cves/2.0?cveId=CVE-2025-6514" target="_blank" rel="noreferrer">NVD (CNA: JFrog)</a></td></tr><tr><td>vLLM</td><td>GHSA-3c86-2m5g-59q7 (無 CVE 編號)</td><td>CVSS 7.8, 特定處理器載入器在 trust_remote_code=False 時仍執行模型內程式碼; 0.28.0 修補, 2026-08-28 公告</td><td><a href="https://github.com/vllm-project/vllm/security/advisories/GHSA-3c86-2m5g-59q7" target="_blank" rel="noreferrer">vLLM GitHub Security Advisory (2026-10-26 核對)</a></td></tr><tr><td>llama.cpp (GGUF 解析)</td><td>CVE-2025-53630</td><td>GGUF 解析器 gguf_init_from_file_impl 的整數溢位, 可造成堆積越界讀寫; 經過設計的 GGUF 模型檔即可觸發, 官方附概念驗證檔; 嚴重度 High; commit 26a48ad 修補, 2025-07-10 公告. 同類問題另見 Cisco Talos 2024 年通報的 CVE-2024-21825 (TALOS-2024-1912)</td><td><a href="https://github.com/ggml-org/llama.cpp/security/advisories/GHSA-vgg9-87g3-85w8" target="_blank" rel="noreferrer">llama.cpp GitHub Security Advisory GHSA-vgg9-87g3-85w8</a></td></tr></tbody></table><p>以 CISA KEV 目錄 (JSON 版本 2026.10.23, 2026-10-26 擷取; 2026-10-27 再次擷取 JSON 失敗, 目錄網頁為 <a href="https://www.cisa.gov/known-exploited-vulnerabilities-catalog" target="_blank" rel="noreferrer">CISA: Known Exploited Vulnerabilities Catalog</a>) 核對: Langflow 列入 CVE-2025-3248, CVE-2026-33017, CVE-2025-34291, CVE-2026-55255, CVE-2026-0770 與 CVE-2026-9198 (IBM Langflow); n8n 列入 CVE-2025-68613; LiteLLM 列入 CVE-2026-42208, CVE-2026-42271 與 CVE-2026-59822. 上表的 Langflow CVE-2026-0768 與 n8n CVE-2026-21858 不在該目錄內. 目錄 JSON 檔: <a href="https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json" target="_blank" rel="noreferrer">CISA KEV JSON</a>.</p><h2 id="其他補充來源" tabindex="-1">其他補充來源 <a class="header-anchor" href="#其他補充來源" aria-label="Permalink to &quot;其他補充來源&quot;">​</a></h2><ul><li>Langflow CVE-2026-0768 的利用觀測: <a href="https://labs.cloudsecurityalliance.org/research/csa-research-note-langflow-ai-framework-credential-harvestin/" target="_blank" rel="noreferrer">CSA 研究筆記: Langflow AI framework credential harvesting (2026-09-04)</a>, <a href="https://securityaffairs.com/198270/hacking/hackers-target-langflow-in-cve-2026-0768-attacks/" target="_blank" rel="noreferrer">Security Affairs: Hackers target Langflow in CVE-2026-0768 attacks (二手來源)</a></li><li>LiteLLM 預定公開的漏洞: <a href="https://docs.litellm.ai/blog/security-incident-oct-21-2026" target="_blank" rel="noreferrer">LiteLLM 官方事故報告 (2026-10-21)</a>, <a href="https://socradar.io/blog/litellm-supply-chain-attack-pypi-docker/" target="_blank" rel="noreferrer">SOCRadar: New LiteLLM supply chain attack hits PyPI and Docker (二手來源)</a>, <a href="https://docs.litellm.ai/blog/tags/security" target="_blank" rel="noreferrer">LiteLLM 官方部落格 security 標籤</a></li><li>GGUF 解析漏洞的早期案例: <a href="https://talosintelligence.com/vulnerability_reports/TALOS-2024-1912" target="_blank" rel="noreferrer">Cisco Talos: TALOS-2024-1912 (CVE-2024-21825)</a></li><li>gVisor 版本: 以 git 直接查詢官方儲存庫的 tag 確認 (2026-10-27), 日期為 tag 所指提交的日期; 正式發布頁的上架日可能晚幾天.</li></ul><h2 id="已知的所有權變動" tabindex="-1">已知的所有權變動 <a class="header-anchor" href="#已知的所有權變動" aria-label="Permalink to &quot;已知的所有權變動&quot;">​</a></h2><table tabindex="0"><thead><tr><th>專案</th><th>變動</th><th>來源</th></tr></thead><tbody><tr><td>promptfoo</td><td>OpenAI 於 2026-03-09 宣布收購, 聲明維持開源 (授權條款見<a href="/lanai-handbook/ref/licenses">授權速查</a>)</td><td><a href="https://openai.com/index/openai-to-acquire-promptfoo/" target="_blank" rel="noreferrer">OpenAI 公告</a>, <a href="https://www.promptfoo.dev/blog/promptfoo-joining-openai/" target="_blank" rel="noreferrer">Promptfoo 公告</a></td></tr><tr><td>Langfuse</td><td>ClickHouse 公司於 2026-01-16 收購, 核心功能維持 MIT 授權</td><td><a href="https://clickhouse.com/blog/clickhouse-acquires-langfuse-open-source-llm-observability" target="_blank" rel="noreferrer">ClickHouse 公告</a></td></tr><tr><td>LibreChat</td><td>ClickHouse 於 2025-11-04 收購, 公告稱既有部署的運作不變</td><td><a href="https://clickhouse.com/blog/clickhouse-acquires-librechat" target="_blank" rel="noreferrer">ClickHouse 公告</a></td></tr><tr><td>Arize Phoenix</td><td>Dynatrace 於 2026-10-01 公告完成收購 Arize, Arize 表示持續支援 Phoenix</td><td><a href="https://dynatrace.com/news/press-release/dynatrace-completes-acquisition-of-arize" target="_blank" rel="noreferrer">Dynatrace 新聞稿</a></td></tr><tr><td>LLM Guard</td><td>Protect AI 儲存庫已於 2026-07-09 封存</td><td><a href="https://github.com/protectai/llm-guard" target="_blank" rel="noreferrer">GitHub 儲存庫</a></td></tr></tbody></table><p>收購方目前都承諾維持開源, 但屬長期鎖定風險, 需持續追蹤.</p>',16)])])}const p=e(l,[["render",i]]);export{b as __pageData,p as default};
